const s = $('Post Settings').item.json;
const answers = $('Ask What You Learned').item.json.data || {};

// 🔎 Gemini item കണ്ടെത്തുക — 'content.parts' ഘടനയിലും
const allItems = $input.all().map(i => i.json);
const geminiItem = allItems.find(it =>
  it.content?.parts
);

// 📝 Body എടുക്കൽ — എല്ലാ ഫോർമാറ്റുകളും support
let body = '';

if (geminiItem?.content?.parts) {
  // ✅ ഫോർമാറ്റ് 1: n8n Gemini node → { content: { parts: [{text}] } }
  body = geminiItem.content.parts.map(p => p.text).filter(Boolean).join('\n');
} else if (Array.isArray(geminiItem?.candidates)) {
  // ഫോർമാറ്റ് 2: raw API → { candidates: [{ content: { parts } }] }
  const first = geminiItem.candidates[0];
  body = first?.content?.parts?.map(p => p.text).filter(Boolean).join('\n')
      ?? first?.content?.[0]?.text ?? '';
} else if (typeof geminiItem?.output === 'string') {
  body = geminiItem.output;
} else if (Array.isArray(geminiItem?.output)) {
  body = geminiItem.output[0]?.text ?? String(geminiItem.output[0] ?? '');
}

body = String(body).trim();

const link = String(answers['Code link'] || '').trim();
const header = `Day ${s.DayNumber}/${s.TotalDays} 🚀`;
const esc = (t) => t.replace(/[\\|{}@\[\]()<>#*_~]/g, (m) => '\\' + m);

const plain = [header, ''];
if (body) plain.push(body, '');
const rich = [header, ''];
if (body) rich.push(esc(body), '');

if (link) {
  plain.push('Code: ' + link, '');
  rich.push('Code: ' + esc(link), '');
}

const previewText = plain.join('\n') + '\n' + s.Hashtags + ' @' + s.MentionName;

const urn = String(s.MentionOrgUrn || '').trim();
const tag = urn && /^urn:li:organization:\d+$/.test(urn)
  ? `@[${s.MentionName}](${urn})`
  : '\\@' + s.MentionName;

const commentary = rich.join('\n') + '\n' + s.Hashtags + ' ' + tag;

return { DayNumber: s.DayNumber, previewText, commentary };

